svg.script:
const NS = 'http://www.w3.org/2000/svg';
const D = [2, 1, 3, 2, 1, 2, 3, 1, 2, 2, 1, 3];
const C = 4, RATE = 1.6, BAR = 140;
const COL = {
  q: ['#D3D1C7', '#2C2C2A'],
  r: ['#AFA9EC', '#26215C'],
  d: ['#5DCAA5', '#04342C']
};

let N = 4, ovChecked = false, queue, workers, done, t, last = null, paused = false, ev = '', results = {};

function mk(tag, at, par) {
  const e = document.createElementNS(NS, tag);
  for (const k in at) e.setAttribute(k, at[k]);
  par.appendChild(e);
  return e;
}

const wg = [];
for (let i = 0; i < 12; i++) {
  const g = mk('g', {}, document.getElementById('wk'));
  mk('rect', { class: 'zone', x: 186, y: 40 + i * 26, width: 304, height: 24, rx: 6 }, g);
  const l = mk('text', { class: 'ts', x: 194, y: 52 + i * 26, 'dominant-baseline': 'central' }, g);
  l.textContent = 'W' + (i + 1);
  const bgBar = mk('rect', { x: 274, y: 46 + i * 26, width: BAR, height: 12, rx: 3 }, g);
  bgBar.style.fill = 'var(--border)';
  const bar = mk('rect', { x: 274, y: 46 + i * 26, width: 0, height: 12, rx: 3, fill: '#7F77DD' }, g);
  const sp = mk('text', { class: 'ts', x: 424, y: 52 + i * 26, 'dominant-baseline': 'central' }, g);
  wg.push({ g, bar, sp });
}

const cg = [];
for (let c = 0; c < C; c++) {
  const x = 514 + (c % 2) * 74, y = 50 + Math.floor(c / 2) * 60;
  const g = mk('g', {}, document.getElementById('cores'));
  const r = mk('rect', { x, y, width: 68, height: 50, rx: 8, class: 'zone' }, g);
  r.style.fill = 'var(--bg-neutral)';
  const a = mk('text', { class: 'th', x: x + 34, y: y + 18, 'text-anchor': 'middle', 'dominant-baseline': 'central' }, g);
  a.textContent = 'core ' + (c + 1);
  const b = mk('text', { class: 'ts', x: x + 34, y: y + 35, 'text-anchor': 'middle', 'dominant-baseline': 'central' }, g);
  cg.push({ r, b });
}

const chips = [];
for (let j = 0; j < 12; j++) {
  const g = mk('g', { class: 'chip' }, document.getElementById('jobs'));
  const r = mk('rect', { width: 44, height: 22, rx: 6 }, g);
  const tx = mk('text', { class: 'th', x: 22, y: 11, 'text-anchor': 'middle', 'dominant-baseline': 'central' }, g);
  tx.textContent = 'J' + (j + 1);
  chips.push({ g, r, tx });
}

function busyCount() {
  return workers.filter(w => w.job !== null).length;
}

function speed() {
  const b = busyCount();
  if (b <= C) return 1;
  let s = C / b;
  if (ovChecked) s = s / (1 + 0.05 * (b - C));
  return s;
}

function assign() {
  const took = [];
  workers.forEach((w, i) => {
    if (w.job === null && queue.length > 0) {
      w.job = queue.shift();
      w.rem = D[w.job];
      took.push('W' + (i + 1) + ' takes J' + (w.job + 1));
    }
  });
  if (took.length > 0 && took.length < 4) ev = took.join(', ');
}

function updateWorkerButtons() {
  [2, 4, 8, 12].forEach(val => {
    const el = document.getElementById('n-' + val);
    if (val === N) el.classList.add('opt-active');
    else el.classList.remove('opt-active');
  });
}

function reset() {
  updateWorkerButtons();
  queue = D.map((_, i) => i);
  workers = Array.from({ length: N }, () => ({ job: null, rem: 0 }));
  done = [];
  t = 0;
  ev = '';
  last = null;
  wg.forEach((w, i) => {
    w.g.style.opacity = i < N ? 1 : 0;
  });
  assign();
  render();
}

function render() {
  chips.forEach((c, j) => {
    let x, y, s;
    const qi = queue.indexOf(j), di = done.indexOf(j), wi = workers.findIndex(w => w.job === j);
    if (qi >= 0) { x = 22 + (qi % 2) * 54; y = 50 + Math.floor(qi / 2) * 30; s = 'q'; }
    else if (wi >= 0) { x = 222; y = 41 + wi * 26; s = 'r'; }
    else { x = 514 + (di % 3) * 50; y = 208 + Math.floor(di / 3) * 30; s = 'd'; }
    c.g.style.transform = 'translate(' + x + 'px,' + y + 'px)';
    c.r.setAttribute('fill', COL[s][0]);
    c.tx.style.fill = COL[s][1];
  });

  const sp = speed(), b = busyCount();
  workers.forEach((w, i) => {
    wg[i].bar.setAttribute('width', w.job === null ? 0 : BAR * (1 - w.rem / D[w.job]));
    wg[i].sp.textContent = w.job === null ? '' : Math.round(sp * 100) + '% speed';
  });

  cg.forEach((c, k) => {
    c.r.style.fill = k < Math.min(b, C) ? '#AFA9EC' : 'var(--bg-neutral)';
    c.b.style.fill = k < Math.min(b, C) ? '#26215C' : 'var(--text-secondary)';
    c.b.textContent = b === 0 ? 'idle' : b > C ? (b / C).toFixed(1) + ' workers' : (k < b ? '1 worker' : 'idle');
  });

  const st = document.getElementById('status'), evEl = document.getElementById('ev');
  if (done.length === 12) {
    st.textContent = 'All 12 jobs done at t = ' + t.toFixed(1);
    evEl.textContent = '';
  } else {
    st.textContent = 't = ' + t.toFixed(1) + '  |  ' + b + ' busy workers on ' + C + ' cores, each at ' + Math.round(sp * 100) + '% speed';
    evEl.textContent = b > C
      ? 'Workers outnumber cores: the OS time-slices, so every job slows down.'
      : (b === C ? 'Every worker has a core to itself: the cores are fully used.' : 'Fewer workers than cores: some cores sit idle.');
  }
}

function showResults() {
  const ks = Object.keys(results).map(Number).sort((a, b) => a - b);
  const tb = document.getElementById('res');
  const svgEl = document.documentElement;
  const bgEl = document.getElementById('page-bg');

  while (tb.firstChild) tb.removeChild(tb.firstChild);

  if (ks.length === 0) {
    svgEl.setAttribute('viewBox', '0 0 680 492');
    bgEl.setAttribute('height', 492);
    return;
  }

  const h1 = mk('text', { class: 'tbl-th', x: 0, y: 10 }, tb);
  h1.textContent = 'Workers';
  const h2 = mk('text', { class: 'tbl-th', x: 175, y: 10 }, tb);
  h2.textContent = 'Finished at';

  const line = mk('line', { x1: 0, y1: 16, x2: 260, y2: 16, 'stroke-width': 0.5 }, tb);
  line.style.stroke = 'var(--border)';

  ks.forEach((k, idx) => {
    const y = 32 + idx * 22;
    const c1 = mk('text', { class: 'tbl-td', x: 0, y }, tb);
    c1.textContent = k + (k > C ? ' (more than cores)' : '');
    const c2 = mk('text', { class: 'tbl-td', x: 175, y }, tb);
    c2.textContent = 't = ' + results[k].toFixed(1);
  });

  const totalH = 524 + ks.length * 22;
  svgEl.setAttribute('viewBox', '0 0 680 ' + totalH);
  bgEl.setAttribute('height', totalH);
}

function tick(now) {
  if (last === null) last = now;
  const dt = paused ? 0 : Math.min((now - last) / 1000, 0.1) * RATE;
  last = now;
  if (done.length < 12) {
    t += dt;
    const s = speed();
    workers.forEach(w => {
      if (w.job !== null) {
        w.rem -= dt * s;
        if (w.rem <= 0) {
          done.push(w.job);
          w.job = null;
        }
      }
    });
    assign();
    if (done.length === 12) {
      results[N] = t;
      showResults();
    }
    render();
  }
  requestAnimationFrame(tick);
}

[2, 4, 8, 12].forEach(val => {
  document.getElementById('n-' + val).addEventListener('click', () => {
    N = val;
    reset();
  });
});

document.getElementById('ov').addEventListener('click', () => {
  ovChecked = !ovChecked;
  document.getElementById('ov').setAttribute('aria-checked', String(ovChecked));
  document.getElementById('ov-check').style.opacity = ovChecked ? 1 : 0;
  document.getElementById('ov-box').style.fill = ovChecked ? 'var(--bg-accent)' : 'transparent';
  results = {};
  showResults();
  reset();
});

document.getElementById('replay').addEventListener('click', () => {
  reset();
  paused = false;
  document.getElementById('pp-lbl').textContent = 'Pause';
});

document.getElementById('pp').addEventListener('click', () => {
  paused = !paused;
  document.getElementById('pp-lbl').textContent = paused ? 'Play' : 'Pause';
});

reset();
setTimeout(() => {
  last = null;
  requestAnimationFrame(tick);
}, 500);
